    {
      "registryType": "pypi",
      "identifier": "kiln3d",
      "version": "1.5.0",
      "runtimeHint": "uvx",
      "packageArguments": [
        {
          "type": "positional",
          "value": "serve"
        }
      ],
      "transport": {
        "type": "stdio"
